{
  "type_map": {},
  "constraints": [
    {
      "id": "R1",
      "category": "math",
      "alternatives": [
        "df['FLOW_DURATION_MILLISECONDS'] == df['FLOW_END_MILLISECONDS'] - df['FLOW_START_MILLISECONDS']"
      ],
      "features": [
        "FLOW_DURATION_MILLISECONDS",
        "FLOW_END_MILLISECONDS",
        "FLOW_START_MILLISECONDS"
      ],
      "rationale": "Flow duration is defined as end time minus start time."
    },
    {
      "id": "R2",
      "category": "math",
      "alternatives": [
        "(df['FLOW_DURATION_MILLISECONDS'] == 0) | (np.isclose(df['SRC_TO_DST_SECOND_BYTES'], 1000 * df['IN_BYTES'] / df['FLOW_DURATION_MILLISECONDS'], rtol=1e-5))",
        "(df['DURATION_IN'] == 0) | (np.isclose(df['SRC_TO_DST_SECOND_BYTES'], 1000 * df['IN_BYTES'] / df['DURATION_IN'], rtol=1e-5))"
      ],
      "features": [
        "SRC_TO_DST_SECOND_BYTES",
        "IN_BYTES",
        "FLOW_DURATION_MILLISECONDS",
        "DURATION_IN"
      ],
      "rationale": "Bytes per second is bytes divided by duration in seconds; duration may be total flow duration or direction-specific."
    },
    {
      "id": "R3",
      "category": "math",
      "alternatives": [
        "(df['FLOW_DURATION_MILLISECONDS'] == 0) | (np.isclose(df['DST_TO_SRC_SECOND_BYTES'], 1000 * df['OUT_BYTES'] / df['FLOW_DURATION_MILLISECONDS'], rtol=1e-5))",
        "(df['DURATION_OUT'] == 0) | (np.isclose(df['DST_TO_SRC_SECOND_BYTES'], 1000 * df['OUT_BYTES'] / df['DURATION_OUT'], rtol=1e-5))"
      ],
      "features": [
        "DST_TO_SRC_SECOND_BYTES",
        "OUT_BYTES",
        "FLOW_DURATION_MILLISECONDS",
        "DURATION_OUT"
      ],
      "rationale": "Bytes per second is bytes divided by duration in seconds; duration may be total flow duration or direction-specific."
    },
    {
      "id": "R4",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_AVG_THROUGHPUT'] == 8 * df['SRC_TO_DST_SECOND_BYTES']"
      ],
      "features": [
        "SRC_TO_DST_AVG_THROUGHPUT",
        "SRC_TO_DST_SECOND_BYTES"
      ],
      "rationale": "Throughput in bps is 8 times bytes per second."
    },
    {
      "id": "R5",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_AVG_THROUGHPUT'] == 8 * df['DST_TO_SRC_SECOND_BYTES']"
      ],
      "features": [
        "DST_TO_SRC_AVG_THROUGHPUT",
        "DST_TO_SRC_SECOND_BYTES"
      ],
      "rationale": "Throughput in bps is 8 times bytes per second."
    },
    {
      "id": "R6",
      "category": "math",
      "alternatives": [
        "df['NUM_PKTS_UP_TO_128_BYTES'] + df['NUM_PKTS_128_TO_256_BYTES'] + df['NUM_PKTS_256_TO_512_BYTES'] + df['NUM_PKTS_512_TO_1024_BYTES'] + df['NUM_PKTS_1024_TO_1514_BYTES'] == df['IN_PKTS'] + df['OUT_PKTS']"
      ],
      "features": [
        "NUM_PKTS_UP_TO_128_BYTES",
        "NUM_PKTS_128_TO_256_BYTES",
        "NUM_PKTS_256_TO_512_BYTES",
        "NUM_PKTS_512_TO_1024_BYTES",
        "NUM_PKTS_1024_TO_1514_BYTES",
        "IN_PKTS",
        "OUT_PKTS"
      ],
      "rationale": "The sum of packets in all size categories equals total packets."
    },
    {
      "id": "R7",
      "category": "math",
      "alternatives": [
        "df['TCP_FLAGS'] == (df['CLIENT_TCP_FLAGS'] | df['SERVER_TCP_FLAGS'])"
      ],
      "features": [
        "TCP_FLAGS",
        "CLIENT_TCP_FLAGS",
        "SERVER_TCP_FLAGS"
      ],
      "rationale": "Total TCP flags are the bitwise OR of client and server flags."
    },
    {
      "id": "R8",
      "category": "math",
      "alternatives": [
        "df['SHORTEST_FLOW_PKT'] <= df['LONGEST_FLOW_PKT']"
      ],
      "features": [
        "SHORTEST_FLOW_PKT",
        "LONGEST_FLOW_PKT"
      ],
      "rationale": "Shortest packet length cannot exceed longest packet length."
    },
    {
      "id": "R9",
      "category": "math",
      "alternatives": [
        "df['MIN_IP_PKT_LEN'] <= df['MAX_IP_PKT_LEN']"
      ],
      "features": [
        "MIN_IP_PKT_LEN",
        "MAX_IP_PKT_LEN"
      ],
      "rationale": "Minimum IP packet length cannot exceed maximum."
    },
    {
      "id": "R10",
      "category": "math",
      "alternatives": [
        "df['MIN_TTL'] <= df['MAX_TTL']"
      ],
      "features": [
        "MIN_TTL",
        "MAX_TTL"
      ],
      "rationale": "Minimum TTL cannot exceed maximum TTL."
    },
    {
      "id": "R11",
      "category": "math",
      "alternatives": [
        "df['LONGEST_FLOW_PKT'] == df['MAX_IP_PKT_LEN']"
      ],
      "features": [
        "LONGEST_FLOW_PKT",
        "MAX_IP_PKT_LEN"
      ],
      "rationale": "Longest flow packet is the same as maximum IP packet length."
    },
    {
      "id": "R12",
      "category": "math",
      "alternatives": [
        "df['SHORTEST_FLOW_PKT'] == df['MIN_IP_PKT_LEN']"
      ],
      "features": [
        "SHORTEST_FLOW_PKT",
        "MIN_IP_PKT_LEN"
      ],
      "rationale": "Shortest flow packet is the same as minimum IP packet length."
    },
    {
      "id": "R13",
      "category": "math",
      "alternatives": [
        "~(df['PROTOCOL'] == 1) | (df['ICMP_TYPE'] // 256 == df['ICMP_IPV4_TYPE'])"
      ],
      "features": [
        "PROTOCOL",
        "ICMP_TYPE",
        "ICMP_IPV4_TYPE"
      ],
      "rationale": "For ICMP flows, ICMP_TYPE encodes type and code; type is ICMP_TYPE // 256."
    },
    {
      "id": "R14",
      "category": "math",
      "alternatives": [
        "df['DURATION_IN'] <= df['FLOW_DURATION_MILLISECONDS']"
      ],
      "features": [
        "DURATION_IN",
        "FLOW_DURATION_MILLISECONDS"
      ],
      "rationale": "Directional duration cannot exceed total flow duration."
    },
    {
      "id": "R15",
      "category": "math",
      "alternatives": [
        "df['DURATION_OUT'] <= df['FLOW_DURATION_MILLISECONDS']"
      ],
      "features": [
        "DURATION_OUT",
        "FLOW_DURATION_MILLISECONDS"
      ],
      "rationale": "Directional duration cannot exceed total flow duration."
    },
    {
      "id": "R16",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_IAT_MIN'] <= df['SRC_TO_DST_IAT_AVG']"
      ],
      "features": [
        "SRC_TO_DST_IAT_MIN",
        "SRC_TO_DST_IAT_AVG"
      ],
      "rationale": "Minimum IAT cannot exceed average IAT."
    },
    {
      "id": "R17",
      "category": "math",
      "alternatives": [
        "df['SRC_TO_DST_IAT_AVG'] <= df['SRC_TO_DST_IAT_MAX']"
      ],
      "features": [
        "SRC_TO_DST_IAT_AVG",
        "SRC_TO_DST_IAT_MAX"
      ],
      "rationale": "Average IAT cannot exceed maximum IAT."
    },
    {
      "id": "R18",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_IAT_MIN'] <= df['DST_TO_SRC_IAT_AVG']"
      ],
      "features": [
        "DST_TO_SRC_IAT_MIN",
        "DST_TO_SRC_IAT_AVG"
      ],
      "rationale": "Minimum IAT cannot exceed average IAT."
    },
    {
      "id": "R19",
      "category": "math",
      "alternatives": [
        "df['DST_TO_SRC_IAT_AVG'] <= df['DST_TO_SRC_IAT_MAX']"
      ],
      "features": [
        "DST_TO_SRC_IAT_AVG",
        "DST_TO_SRC_IAT_MAX"
      ],
      "rationale": "Average IAT cannot exceed maximum IAT."
    }
  ]
}
